/**
 * Where a project generated by `nest new` points before it is connected: the
 * hosted demo, which shows what the dashboard will look like.
 */
export declare const DEMO_URL = "https://www.observe-demo.nestjs.com/dashboard";
export declare const SIGN_UP_URL = "https://observe.nestjs.com";
/**
 * The command that connects a project in one step: it signs the developer in,
 * writes the key pair into `.env` and makes the start scripts load it.
 */
export declare const LINK_COMMAND = "npx @nestjs/observe link";
export interface CredentialsNotice {
    level: "log" | "warn";
    message: string;
}
/**
 * The one line the agent says at start-up when it has no key pair it can send
 * with, so it sends nothing.
 *
 * Two situations look alike from inside the process and want opposite advice.
 * A project fresh from `nest new` still holds the scaffolded placeholders:
 * the fix is to connect it, which `npx @nestjs/observe link` does in one
 * step. A deployed process with the same placeholders, or with nothing at
 * all, is almost always a project that was connected on a laptop: link keeps
 * the pair in `.env`, which is git-ignored and which `node dist/main` never
 * loads, so production needs the two variables set where it runs. Telling
 * that person to create an account sends them looking for something they
 * already have, so under `NODE_ENV=production` the notice names the
 * variables instead.
 *
 * @param scaffold the options still hold `nest new`'s placeholders
 * @param unset which half of the pair is missing, when the options hold no
 * placeholders but lack a key, a secret or both
 */
export declare function describeMissingCredentials(input: {
    scaffold: boolean;
    unset?: "both" | "appKey" | "appSecret";
    production: boolean;
}): CredentialsNotice;
